import{_ as t,c as a,o as r,ah as s}from"./chunks/framework.DX1DJjtl.js";const c=JSON.parse('{"title":"Program","description":"","frontmatter":{},"headers":[],"relativePath":"api/elements/Program.md","filePath":"api/elements/Program.md","lastUpdated":1785349141000}'),i={name:"api/elements/Program.md"};function n(o,e,d,l,h,p){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="program" tabindex="-1">Program <a class="header-anchor" href="#program" aria-label="Permalink to &quot;Program&quot;">​</a></h1><p><em>extends Element</em></p><p>Program: runs another CC program inside the element.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> prog </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> frame</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">addProgram</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, width </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, height </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rom/programs/fun/worm.lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The program draws into an invisible window; its content is copied into the render buffer every frame. Mouse events arrive element-relative when the element is hit, keyboard events while it is focused, and every other event (timers, redstone, ...) is forwarded by a scheduled pump coroutine. Fires &quot;done&quot;(ok, result) and &quot;error&quot;(err, traceback); without an error handler a crashing program takes down the app through the normal Basalt 2 error screen (with the program&#39;s own traceback).</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>path</td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Resolved path of the running program (read-only)</td></tr><tr><td>running</td><td><code>boolean</code></td><td><code>false</code></td><td>Whether a program is currently running (read-only)</td></tr><tr><td>env</td><td><code>table&lt;string, any&gt;|false</code></td><td><code>false</code></td><td>Extra globals merged into the program environment</td></tr><tr><td>background</td><td><code>number|false</code></td><td><code>colors.black</code></td><td>Background color (false = transparent)</td></tr><tr><td>width</td><td><code>number</code></td><td><code>30</code></td><td>Width in terminal cells</td></tr><tr><td>height</td><td><code>number</code></td><td><code>12</code></td><td>Height in terminal cells</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Registrar</th><th>Description</th></tr></thead><tbody><tr><td>done</td><td>:onDone(fn)</td><td>Fired when the program finishes, with (ok, result)</td></tr><tr><td>error</td><td>:onError(fn)</td><td>Fired when the program crashes, with (err, traceback)</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="program-execute-path" tabindex="-1">Program:execute(path, ...) <a class="header-anchor" href="#program-execute-path" aria-label="Permalink to &quot;Program:execute(path, ...)&quot;">​</a></h3><p>Loads and starts a program; extra arguments are passed to it.</p><ul><li><p><strong>path</strong> (<code>string</code>) Program path (resolved via shell if not found directly)</p></li><li><p><strong>...</strong> (<code>any</code>) Program arguments</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rom/programs/fun/worm.lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="program-stop" tabindex="-1">Program:stop() <a class="header-anchor" href="#program-stop" aria-label="Permalink to &quot;Program:stop()&quot;">​</a></h3><p>Stops (closes) the running program coroutine. Unlike a program that finishes on its own, a manual stop fires no &quot;done&quot; event.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="program-terminate" tabindex="-1">Program:terminate() <a class="header-anchor" href="#program-terminate" aria-label="Permalink to &quot;Program:terminate()&quot;">​</a></h3><p>Requests a native, graceful program shutdown and then force-stops a coroutine that ignored the terminate event. Programs using pullEventRaw can release resources; programs using pullEvent end normally via the conventional &quot;Terminated&quot; error.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="program-sendevent-event" tabindex="-1">Program:sendEvent(event, ...) <a class="header-anchor" href="#program-sendevent-event" aria-label="Permalink to &quot;Program:sendEvent(event, ...)&quot;">​</a></h3><p>Injects an event into the program (as if it came from the event queue).</p><ul><li><p><strong>event</strong> (<code>string</code>) The event name</p></li><li><p><strong>...</strong> (<code>any</code>) Event arguments</p></li><li><p><strong>returns</strong> (<code>self</code>)</p></li></ul><h3 id="program-setup" tabindex="-1">Program:setup() <a class="header-anchor" href="#program-setup" aria-label="Permalink to &quot;Program:setup()&quot;">​</a></h3><p>Initializes per-instance state and input handlers.</p><h3 id="program-handlekey-event-a-b" tabindex="-1">Program:handleKey(event, a, b) <a class="header-anchor" href="#program-handlekey-event-a-b" aria-label="Permalink to &quot;Program:handleKey(event, a, b)&quot;">​</a></h3><p>Handles keyboard input while focused.</p><ul><li><strong>event</strong> (<code>string</code>) The key event name (key, key_up, char, paste)</li><li><strong>a</strong> (<code>any</code>) Key code or typed text</li><li><strong>b</strong> (<code>any</code>, optional) Secondary key-event value</li></ul><h3 id="program-destroy" tabindex="-1">Program:destroy() <a class="header-anchor" href="#program-destroy" aria-label="Permalink to &quot;Program:destroy()&quot;">​</a></h3><p>Stops the program before removing the element.</p><ul><li><strong>returns</strong> (<code>self</code>)</li></ul><h3 id="program-render-buf" tabindex="-1">Program:render(buf) <a class="header-anchor" href="#program-render-buf" aria-label="Permalink to &quot;Program:render(buf)&quot;">​</a></h3><p>Renders the element into the buffer.</p><ul><li><strong>buf</strong> (<code>Render</code>) The render buffer (local coordinates, pre-clipped)</li></ul>`,34)])])}const u=t(i,[["render",n]]);export{c as __pageData,u as default};
